"""Get y coordinates of deletion markers to overlay in heatmap.

    These are the linear y coordinates used in the Plotly graph object.
    i.e., the indices of data["heatmap_y_strains"]

    :param parsed_mutations: A dictionary containing multiple merged
        ``get_parsed_gvf_dir`` return "mutations" values.
    :type parsed_mutations: dict
    :return: List of y coordinate values to display deletion markers
    :rtype: list[str]
    """
def get_deletions_y(parsed_mutations: Any) -> object {
    ret = [];
    for (y, strain) in enumerate(parsed_mutations) {
        for pos in parsed_mutations[strain] {
            for mutation in parsed_mutations[strain][pos] {
                deletion = mutation["mutation_type"] == "deletion";
                hidden = mutation["hidden_cell"];
                if (deletion and not hidden) {
                    ret.append(y);
                }
            }
        }
    }
    return ret;
}

"""Returns 1 if the two do not share a language, else 0"""
def sharedLangCost(criterion: Any, frRow: Any, exRow: Any) -> object {
    fluentQ = criterion['fluentQ'];
    learningQ = criterion['learningQ'];
    frLangs = [`set(frRow[fluentQ].split(',')), `set(frRow[learningQ].split(','))];
    exLangs = [`set(exRow[fluentQ].split(',')), `set(exRow[learningQ].split(','))];
    return int(
        (
            len(frLangs[0].union(frLangs[1]).intersection(exLangs[0].union(exLangs[1])))
            == 0
        )
    );
}

"""
    :param long: The DNA sequence to search.
    :param short: DNA sequence that we want to match.
    :return: Sub sequences that has the highest pairing rate.
    """
def `match(long: Any, short: Any) -> object {
    maximum = 0;
    homology = '';
    for i in range(((len(long) - len(short)) + 1)) {
        dna = long[i:(i + len(short))];
        count = 0;
        for j in range(len(short)) {
            if (short[j] == dna[j]) {
                count += 1;
            }
        }
        matched = count / len(short);
        if (matched > maximum) {
            maximum = matched;
            homology = dna;
        }
    }
    return homology;
}

